import dask

class NoGetItem:
    def __getitem__(self, key):
        raise Exception("Oh no!")

@dask.delayed
def identity(x):
    return x

x = identity(NoGetItem())

if __name__ == "__main__":
    print(dask.compute(x, scheduler="processes", optimize_graph=False))
    print(dask.compute(x, scheduler="processes", optimize_graph=True))
    print(dask.compute(x, scheduler="threads", optimize_graph=False))
    print(dask.compute(x, scheduler="sync", optimize_graph=False))
EOF
